#!/usr/bin/env bash
set -euo pipefail
repo=$1
out=$2
[[ ! -e "$out" ]] || { echo 'Output exists' >&2; exit 2; }
mkdir -p "$out"
cd "$repo"
export LEAN_PATH="$out:/dev/shm/pa194-forward-fixed-eleven-repo:/dev/shm/pa194-forward-refl-root-repo:/dev/shm/pa194-forward-refl-root-repo:/dev/shm/pa194-forward-refl-source-repo:/dev/shm/pa194-forward-refl-unified-repo:/dev/shm/pa194-sequent-rules-repo:/dev/shm/pa194-sequent-axiom-repo:/dev/shm/pa194-formula-negation-repo:/dev/shm/pa194-forward-fixed-axiom-repo:/dev/shm/pa194-ordinary-axiom-split-repo:/dev/shm/pa194-paeq-ordinary-class-repo:/dev/shm/pa194-conditional-refutation-repo:/dev/shm/pa194-paeq-induction-code-repo:/dev/shm/pa194-paeq-typed-closure-repo:/dev/shm/pa194-paeq-free-closure-repo:/dev/shm/pa194-paeq-closure-repo:/dev/shm/pa194-paeq-bind-term-repo:/dev/shm/pa194-full-one-level-audit:/dev/shm/pa194-fairness-full-source-replay:/dev/shm/pa194-standard-ordinal-proof-repo:/dev/shm/pa194-ordinal-closed-repo:/dev/shm/pa194-ordinal-uniform-repo:/dev/shm/pa194-close-proof-repo:/dev/shm/pa194-congruence-source-proof-repo:/dev/shm/pa194-empty-source-proof-repo:/dev/shm/pa194-standard-equality-suppliers-repo:/dev/shm/pa194-standard-ordinal-reduction-repo:/dev/shm/pa194-quoted-induction-repo:/dev/shm/pa194-ordinal-suppliers-repo:/dev/shm/pa194-ordinal-fixed-repo:/dev/shm/pa194-ordinal-induction-code-repo:/dev/shm/pa194-ordinal-statement-repo:/dev/shm/pa194-intersection-proof-repo:/dev/shm/pa194-full-sep-open-repo:/dev/shm/pa194-typed-schema-replay:/dev/shm/pa194-reopen-proof-replay:/dev/shm/pa194-full-sep-theory-replay:/dev/shm/pa194-unclose-envelope-replay:/dev/shm/pa194-ordinal-internal-work:/dev/shm/pa194-term-scope-repo:/dev/shm/pa194-coherence-probe:/dev/shm/pa194-forward-formula-correct-repo:/dev/shm/pa194-forward-term-correct-repo:/dev/shm/pa194-closed-root-formula-repo:/dev/shm/pa194-formula-dispatcher-repo:/dev/shm/pa194-term-dispatcher-repo:/dev/shm:/dev/shm/pa194-paeq-term-formula-tree-replay:/dev/shm/pa194-term-formula-paeq-baseline:/dev/shm/pa194-multiplication-code-replay:/dev/shm/pa194-addition-code-replay:/dev/shm/pa194-paeq-template-compose-replay:/dev/shm/pa194-paeq-ordinal-params-replay:/dev/shm/pa194-paeq-ordinal-values-replay:/dev/shm/pa194-source-template-replay:/dev/shm/pa194-uniform-fully-closed-replay:/dev/shm/pa194-uniform-closure-replay:/dev/shm/pa194-fully-closed-replay:/dev/shm/pa194-model-separation-full-replay:/dev/shm/pa194-model-separation-seeded-replay:/dev/shm/pa194-model-closure-definability-replay:/dev/shm/pa194-model-closure-replay:/dev/shm/pa194-general-separation-replay:/dev/shm/pa194-ranked-open-separation-replay-v3:/dev/shm/pa194-closed-sep-theory-replay:/dev/shm/pa194-uniform-sep-combined-replay:/dev/shm/pa194-standard-no-free-replay:/dev/shm/pa194-closed-sep-classifier-replay:/dev/shm/pa194-generic-sim-replay:/dev/shm/pa194-adjunctive-sim-v2-replay:/dev/shm/pa194-shift-interface-replay:/dev/shm/pa194-unrestricted-existential-v2-replay:/dev/shm/pa194-qf-ranked-existential-audit:/dev/shm/pa194-adjunctive-admission-audit:/dev/shm/pa194-general-shift-replay:/dev/shm/pa194-general-reverse-shift-replay:/dev/shm/pa194-unrestricted-all-replay:/dev/shm/pa194-general-freshness-audit:/dev/shm/pa194-observational-general-audit:/dev/shm/pa194-full-one-level-audit:$(lake env printenv LEAN_PATH)"
logic="$repo/Computability/BusyBeaver/Research/PA/pa194-work/pa194-model-logic"
guarded="$repo/Computability/BusyBeaver/Research/PA/pa194-work/pa194-guarded-compiler"
lean -j1 -R "$logic" -M 7000 -o "$out/PA194ConditionalRefutation.olean" "$logic/PA194ConditionalRefutation.lean" > "$out/PA194ConditionalRefutation.log" 2>&1
if rg -q "sorryAx|declaration uses 'sorry'" "$out/PA194ConditionalRefutation.log"; then exit 1; fi
for pair in PA194GuardedCompile:5 PA194TranslateShift:4 PA194TranslateSubst:3 PA194TranslateExt:7 PA194GuardedCalculus:5 PA194TrCompile:2 PA194Leibniz:4 PA194TermNames:4 PA194ValueBody:6 PA194Schematic:6; do
  mod=${pair%:*}; expected=${pair#*:}
  lean -j1 -R "$guarded" -M 7000 -o "$out/$mod.olean" "$guarded/$mod.lean" > "$out/$mod.log" 2>&1
  if rg -q "sorryAx|declaration uses 'sorry'" "$out/$mod.log"; then exit 1; fi
  [[ $(rg -c 'depends on axioms:' "$out/$mod.log") -eq "$expected" ]]
  cat "$out/$mod.log"
done
printf '%s\n' 'PASS: guarded compiler, incrementally rebuilt with staged dependencies.'
